'use strict';
(()=>{
  const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let ext={index:[],popular:[],quiz:[]},at=0,score=0,answered=false;
  function drawPopular(){let q=$('#popular-filter').value.trim().toLowerCase();let list=ext.popular.filter(x=>[x.number,x.part,x.title].join(' ').toLowerCase().includes(q));$('#popular-list').innerHTML=list.map(x=>`<article class="popular-row"><div class="pop-code">СТ. ${esc(x.number)} ${x.part?'· Ч. '+esc(x.part):''}</div><div class="pop-title">${esc(x.title)}<small>${esc(x.other)}</small></div><div class="pop-stars" aria-label="${x.stars?x.stars+' звёзд':'от 1 до 5 звёзд'}">${x.stars?'★'.repeat(x.stars):'★–★★★★★'}<span>${x.stars?'☆'.repeat(5-x.stars):''}</span></div><div class="pop-term">${esc(x.term)}<small>лишения свободы</small></div><a href="${esc(x.url)}" target="_blank" rel="noopener" aria-label="Открыть статью ${esc(x.number)} на форуме">↗</a></article>`).join('')||'<p class="empty">Ничего не найдено. Попробуйте другой запрос.</p>'}
  function drawIndex(){let q=$('#index-filter').value.trim().toLowerCase();let list=ext.index.filter(x=>(x.number+' '+x.title).toLowerCase().includes(q));$('#index-count').textContent=`${list.length} из ${ext.index.length}`;$('#uk-list').innerHTML=list.map(x=>`<a id="uk-${esc(x.number)}" href="https://forum.russia.online/threads/ugolovnyi-kodeks-ro.39487/" target="_blank" rel="noopener"><b>${esc(x.number)}</b><span>${esc(x.title)}</span><span aria-hidden="true">↗</span></a>`).join('')||'<p class="empty">Такой статьи в загруженном оглавлении нет.</p>';if(q)$('#index-details').open=true}
  function shuffle(xs){let a=[...xs];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
  function renderQuiz(){answered=false;let q=ext.quiz[at];$('#quiz-feedback').innerHTML='';$('#quiz-next').disabled=true;$('#quiz-score').textContent='Верно: '+score;$('#quiz-progress').textContent=`Ситуация ${at+1} / ${ext.quiz.length}`;$('#quiz-bar').style.width=`${at/ext.quiz.length*100}%`;$('#quiz-question').textContent=q.question;$('#quiz-options').innerHTML=shuffle(q.options.map((value,index)=>({value,index}))).map(x=>`<button type="button" data-option="${x.index}">${esc(x.value)}</button>`).join('')}
  function finish(){let n=ext.quiz.length;$('#quiz-progress').textContent='Тест завершён';$('#quiz-score').textContent=`Верно: ${score} из ${n}`;$('#quiz-bar').style.width='100%';$('#quiz-question').textContent=`Результат: ${score} / ${n}`;$('#quiz-options').innerHTML='';$('#quiz-feedback').innerHTML='<p>Повторите сложные ситуации и сверьтесь с первоисточниками.</p>';$('#quiz-next').disabled=true}
  $('#popular-filter').addEventListener('input',drawPopular);$('#index-filter').addEventListener('input',drawIndex);
  $('#quiz-options').addEventListener('click',e=>{let b=e.target.closest('[data-option]');if(!b||answered)return;answered=true;let q=ext.quiz[at],good=Number(b.dataset.option)===q.correct;if(good)score++;for(let el of $('#quiz-options').querySelectorAll('button')){el.disabled=true;if(Number(el.dataset.option)===q.correct)el.classList.add('correct');else if(el===b)el.classList.add('incorrect')}$('#quiz-score').textContent='Верно: '+score;$('#quiz-feedback').innerHTML=`<strong>${good?'Верно':'Не совсем'}</strong><p>${esc(q.explanation)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener">${esc(q.source)} ↗</a>`;$('#quiz-next').disabled=false;$('#quiz-next').textContent=at===ext.quiz.length-1?'Показать результат →':'Следующий вопрос →'});
  $('#quiz-next').addEventListener('click',()=>{if(!answered)return;at++;if(at===ext.quiz.length)finish();else renderQuiz()});$('#quiz-restart').addEventListener('click',()=>{at=0;score=0;renderQuiz()});
  document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#uk-"]');if(a){$('#index-filter').value='';drawIndex();$('#index-details').open=true;let target=document.getElementById(a.getAttribute('href').slice(1));if(target){e.preventDefault();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});target.focus({preventScroll:true})}}});
  fetch('./extended.json').then(r=>{if(!r.ok)throw Error('data');return r.json()}).then(x=>{ext=x;window.ukIndex=x.index;drawPopular();drawIndex();renderQuiz();if(typeof search==='function')search()}).catch(()=>{$('#popular-list').textContent='Не удалось загрузить данные. Проверьте extended.json.';$('#quiz-question').textContent='Не удалось загрузить вопросы.'});
  if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const nodes=document.querySelectorAll('main section:not(#home)');const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');io.unobserve(e.target)}}),{threshold:.05});nodes.forEach(el=>{el.classList.add('reveal');io.observe(el)})}
})();
